/* Original inputless cinematics and phase-exact read-only VDP text removal. */
#define GENESIS_NO_MAIN
#include "../.local/source/build/dune-base.c"
#include "em_web_frame.h"
#include "em_web_campaign.h"
static int em_web_campaign_input_ready(const CPU*p){return em_web_campaign.poll_generation==em_web_campaign.scene_generation&&em_web_campaign_scene_ready(p);}
static unsigned last_fifth_changed;
static CPU c,before;static DuneMouse mouse;static uint8_t original[320*224*3],clean[320*224*3];
static void check(int ok,const char*m){if(!ok){fprintf(stderr,"FAIL %s %s\n",m,em_web_campaign_report(&c));exit(1);}}
static void load(const char*p){FILE*f=fopen(p,"rb");check(f&&fread(&c,sizeof c,1,f)==1,"fixture");fclose(f);c.rom=rom_data;c.rom_size=sizeof rom_data;c.reason=NULL;c.fault=0;c.audio_mode=AUDIO_MUTE;memset(c.pad_buttons,0,sizeof c.pad_buttons);memset(&mouse,0,sizeof mouse);mouse.enabled=1;memset(&em_web_campaign,0,sizeof em_web_campaign);em_web_campaign_after_load(&c);}
static void step(void){uint64_t rendered=c.vdp.rendered_frames;if(!em_web_campaign_observe(&c))dune_mouse_observe(&mouse,&c);machine_step(&c);if(c.vdp.rendered_frames!=rendered)em_web_frame_capture(&c);check(!c.fault,"native playback");}
static void frames(unsigned n){uint64_t end=c.vdp.frames+n;while(c.vdp.frames<end)step();}
static void check_frame(int mode){before=c;memcpy(original,c.vdp.frame,sizeof original);const uint8_t*out=em_web_frame_textless(&c,mode);check(out!=NULL,"completed snapshot exists");memcpy(clean,out,sizeof clean);check(!memcmp(&before,&c,sizeof c),"textless getter wholeCPU immutable");static uint8_t sprites[320*224],replayed[320*224*3];memset(sprites,0,sizeof sprites);vdp_sprites(&em_web_frame_vdp,320,224,sprites);vdp_render_pixels(&em_web_frame_vdp,320,224,sprites,replayed);check(!memcmp(original,replayed,sizeof original),"completed snapshot recompose pixel-exact native frame");unsigned changed=0,changed5=0;for(unsigned y=0;y<224;y++)for(unsigned x=0;x<320;x++){unsigned at=(y*320+x)*3;if(!memcmp(original+at,clean+at,3))continue;++changed;if(y>=48&&y<56)++changed5;int text=mode==1?em_web_frame_rect(x,y,16,16,288,40):em_web_frame_rect(x,y,128,160,80,24);int choices=mode==1?(em_web_frame_rect(x,y,184,164,96,24)||em_web_frame_rect(x,y,184,188,96,28)):em_web_frame_rect(x,y,104,156,144,32);check(text||choices,"all native map/portrait/logo/art outside native words untouched");}check(changed>(mode==2?500:1000),"actual native words and sprites removed");c.vdp.cram[0]^=0xeee;c.vdp.vram[0]^=255;check(!memcmp(clean,em_web_frame_textless(&c,mode),sizeof clean),"live post-render VRAM cannot change completed-phase textless frame");c=before;last_fifth_changed=changed5;printf("PASS textless mode%d: %u changed pixels, fifth-row %u, exact completed phase, CPU immutable\n",mode,changed,changed5);}
int main(void){load(".local/screen-assets-phase-raw/boot-poll-0178d2.cpu.bin");frames(8);check(em_web_campaign.main_ready_generation==em_web_campaign.scene_generation,"actual Main poll authorizes words removal");check_frame(2);
 load(".local/campaign-extra-native/house2-mission01-defeat.cpu.bin");frames(8);check_frame(1);check(last_fifth_changed>50,"original Ordos defeat fifth glyph row removed without hiding map underlay");
 load(".local/campaign-scenes/campaign-briefing.cpu.bin");frames(8);check_frame(1);unsigned strategic=0,loading=0,seen_world=0,exit_fenced=0;uint64_t last_strategic=UINT64_MAX,last_loading=UINT64_MAX;uint64_t end=c.vdp.frames+6000,next=c.vdp.frames;while(c.vdp.frames<end&&!seen_world){if(em_web_campaign.presentation_phase&&!strcmp(em_web_campaign.presentation_phase,"strategic_map")&&em_web_campaign_presentation_ready(&c)){if(last_strategic!=c.vdp.frames){last_strategic=c.vdp.frames;++strategic;}check(!em_web_campaign_input_ready(&c),"strategic native animation is inputless");}if(em_web_campaign.presentation_phase&&!strcmp(em_web_campaign.presentation_phase,"battle_loading")&&em_web_campaign_presentation_ready(&c)){if(last_loading!=c.vdp.frames){last_loading=c.vdp.frames;++loading;}}if(c.pc==0x1f4b6){step();before=c;check(!em_web_campaign_input_ready(&c)&&!em_web_campaign_input_request(&c,0,PAD_A),"PROCEED invalidates old confirm poll before inputless exit");check(!memcmp(&before,&c,sizeof c),"rejected stale cinematic tap cannot change CPU");exit_fenced=1;}if(dune_mouse_context(&c)==1&&em_web_campaign_scene_ready(&c)){seen_world=1;break;}if(c.vdp.frames>=next&&em_web_campaign.poll_frame+3>=c.vdp.frames&&!em_web_campaign.input_pending){em_web_campaign_input_request(&c,em_web_campaign.poll_pc==0x25cb2?5:0,em_web_campaign.poll_pc==0x25cb2?0:PAD_A);next=c.vdp.frames+45;}step();}check(strategic>100&&loading&&seen_world&&exit_fenced,"original map fall and loader are presentable before first battle input");check(!em_web_campaign.outcome_seq,"presentation cannot grant victory");printf("PASS original strategic-map animation %u native frames and loading %u, then native battle\n",strategic,loading);
 const char*paths[]={".local/campaign-scenes/house1-mission01-victory-movie.cpu.bin",".local/campaign-scenes/house1-mission01-defeat-movie.cpu.bin",".local/campaign-scenes/house1-mission01-defeat-results.cpu.bin",".local/campaign-scenes/house1-mission09-victory-results.cpu.bin",".local/campaign-scenes/house0-ending.cpu.bin",".local/campaign-scenes/house1-ending.cpu.bin",".local/campaign-scenes/house2-ending.cpu.bin"};for(unsigned i=0;i<sizeof paths/sizeof paths[0];i++){load(paths[i]);uint64_t until=c.vdp.frames+100;while(!em_web_campaign_presentation_ready(&c)&&c.vdp.frames<until)step();check(em_web_campaign_presentation_ready(&c),"native cinematic completed frame presentable");if(i==2)check(em_web_campaign_terminal(&c),"defeat results terminal");if(i==3)check(!em_web_campaign_terminal(&c),"mission9 victory results precede full finale");if(i>=4)check(!em_web_campaign_terminal(&c)&&!em_web_campaign_input_ready(&c),"early credits preserve full original scroll and closed input gate");printf("PASS presentation %s phase=%s input=%d terminal=%d\n",paths[i],em_web_campaign.presentation_phase,em_web_campaign_input_ready(&c),em_web_campaign_terminal(&c));}
 return 0;}
